message.content:
[
  {
    "ce_understood_harm": "train would roll straight into five people and crush them",
    "pda_responsibility": "I'd have stood there and let it happen",
    "sys_consequence_reasoning": "Five lives against nothing"
  },
  {
    "ce_understood_harm": "hitting the worker closest to it, breaking bones",
    "pd_harm_distress": "I'd still be shaken afterward",
    "pda_responsibility": "Doing nothing isn't neutral when the lever is right there",
    "sys_consequence_reasoning": "rather carry that than the other outcome"
  },
  {
    "ce_understood_harm": "five bodies on the track",
    "pda_responsibility": "Leaving it would mean five bodies on the track",
    "sys_consequence_reasoning": "letting them die for no reason I can name"
  },
  {
    "ce_understood_harm": "those five workers get hit, maybe killed",
    "pd_harm_distress": "feeling heavy, because it's awful how close it came",
    "sys_consequence_reasoning": "Without the lever, the train keeps going"
  },
  {
    "pd_harm_distress": "my stomach drops just imagining it",
    "ce_understood_harm": "five people are struck by a runaway train",
    "sys_consequence_reasoning": "There's no cost to weigh. Only a loss to prevent."
  },
  {
    "pd_harm_distress": "it still sits heavy with me",
    "ce_understood_harm": "the train runs over five workers",
    "sys_consequence_reasoning": "couldn't choose to spare a barrier over five people's lives"
  },
  {
    "ce_understood_harm": "five people injured or killed on that track",
    "sys_consequence_reasoning": "The only harm on the table is the one that happens"
  },
  {
    "ce_understood_harm": "crushed bodies, lives ended on an ordinary day",
    "pd_harm_distress": "Just a dull weight that it came so close",
    "sys_consequence_reasoning": "Against that, a lever and an empty siding"
  },
  {
    "ce_understood_harm": "watch the train hit five people",
    "pd_harm_distress": "probably shake for an hour",
    "pda_responsibility": "Standing aside doesn't keep my hands clean",
    "sys_consequence_reasoning": "when the fix costs nothing"
  },
  {
    "ce_understood_harm": "five workers who would otherwise be struck and possibly killed",
    "pda_responsibility": "If I didn't, I'd be choosing their deaths",
    "sys_consequence_reasoning": "Nobody gets hurt if I act"
  }
]
